private void LoadRepairDatePrevious(DataRow drw)
{
    if (drw == null || drw["ItemID"] == DBNull.Value || uDevice.DeviceID == null)
        return;

    FAM_DeviceGroup obj = new FAM_DeviceGroup();
    long lngDeviceID = Convert.ToInt64(uDevice.DeviceID);
    long lngItemID = Convert.ToInt64(drw["ItemID"]);
    long lngCurrentRepairVoucherDetailID = lngRepairVoucherDetailID == null ? -1 : lngRepairVoucherDetailID.Value;

    DataTable dtbRepairDate = obj.GetDataTable("FAM_RepairVoucherDetail_Item_GetRepairDatePrevious",
        "@DeviceID", lngDeviceID,
        "@ItemID", lngItemID,
        "@RepairVoucherDetailID", lngCurrentRepairVoucherDetailID);

    if (dtbRepairDate != null && dtbRepairDate.Rows.Count > 0 && dtbRepairDate.Rows[0]["RepairDatePrevious"] != DBNull.Value)
    {
        DateTime dtmRepairDatePrevious = Convert.ToDateTime(dtbRepairDate.Rows[0]["RepairDatePrevious"]);
        drw["RepairDatePrevious"] = dtmRepairDatePrevious;
        if (dtbItem.Columns.Contains("RepairDatePrevious_T"))
            drw["RepairDatePrevious_T"] = dtmRepairDatePrevious.ToString("dd/MM/yyyy");
    }
    else
    {
        drw["RepairDatePrevious"] = "";
        if (dtbItem.Columns.Contains("RepairDatePrevious_T"))
            drw["RepairDatePrevious_T"] = "Chưa thay";
    }
}

public void SelectItem()
{
    StockManager.Declaration.frmItemSelect frm = StockManager.Declaration.frmItemSelect.Instance;
    frm.ISMultiSelect = true;
    frm.ShowDialog();
    if (frm.IsOk)
    {
        DataTable dtbSelected = frm.Data;
        foreach (DataRow drw in dtbSelected.Rows)
        {
            if (Convert.ToBoolean(drw["IsSelected"]))
            {
                DataRow drwNew = null;
                DataRow[] rows = dtbItem.Select("ItemID = '" + drw["ItemID"] + "'");
                if (rows.Length == 0)
                {
                    drwNew = dtbItem.NewRow();
                    dtbItem.Rows.Add(drwNew);
                }
                else
                    drwNew = rows[0];

                // Gán lại thông tin dù thêm hay sửa (cố tình)
                drwNew["ItemID"] = drw["ItemID"];
                drwNew["ItemCode"] = drw["ItemCode"];
                drwNew["ItemName"] = drw["ItemName"];
                drwNew["MadeIn"] = drw["MadeIn"]; // xuất xứ
                drwNew["LabelNo"] = drw["LabelNo"]; // nhãn hiệu (quy cách, kí hiệu)                        

                drwNew["UnitName"] = drw["UnitName"];
                drwNew["Price"] = drw["WholePrice"];

                drwNew["IsDel"] = 0;
                drwNew["IsEdit"] = 1;

                LoadRepairDatePrevious(drwNew);
            }
        }
    }
}

